type Card = { title: string; description: string; href?: string; action?: string; tag?: string }

export function PortalButton({children,href,onClick,variant="primary",disabled=false,size="middle"}:{children:React.ReactNode;href?:string;onClick?:()=>void;variant?:"primary"|"secondary"|"dark"|"primary-light"|"light";disabled?:boolean;size?:"middle"|"default"|"small"}) {
  const className=`por-btn por-btn-${variant} por-btn-${size} por-btn-lg-default`
  return href && !disabled ? <a className={className} href={href}>{children}</a> : <button className={className} type="button" disabled={disabled} onClick={onClick}>{children}</button>
}
export function resolvePortalHeaderLayout({viewport,available,logo,nav,actions,fullSearch=160,iconSearch=32,gap=24}:{viewport:number;available:number;logo:number;nav:number;actions:number;fullSearch?:number;iconSearch?:number;gap?:number}){
 if(viewport<=768)return {mobile:true,compactSearch:true,wrapped:false}
 const base=logo+nav+actions+gap*2;const compactSearch=base+fullSearch>available
 return {mobile:false,compactSearch,wrapped:base+(compactSearch?iconSearch:fullSearch)>available}
}
export function PortalHeader({scene="product",links,variant="compact",actionEntries,searchEnabled,mobileMenu}:{scene?:"product"|"developer";links:Link[];variant?:"compact"|"site";actionEntries?:Link[];searchEnabled?:boolean;mobileMenu?:PortalMobileMenuGroup[]}) {
 const [open,setOpen]=React.useState(false);const [searchOpen,setSearchOpen]=React.useState(false);const [layout,setLayout]=React.useState({mobile:false,compactSearch:false,wrapped:false})
 const menu=React.useRef<HTMLButtonElement>(null);const header=React.useRef<HTMLElement>(null);const inner=React.useRef<HTMLDivElement>(null);const nav=React.useRef<HTMLElement>(null);const id=React.useId();const searchId=React.useId();const search=searchEnabled??(variant==="site"||scene==="developer")
 React.useEffect(()=>{const el=inner.current;if(!el)return;let frame=0;function update(){const el=inner.current,h=header.current,n=nav.current;if(!el||!h||!n)return;const viewport=window.innerWidth;const style=getComputedStyle(el);const gap=parseFloat(style.columnGap)||24;const available=el.clientWidth-parseFloat(style.paddingLeft)-parseFloat(style.paddingRight);const logo=el.querySelector<HTMLElement>(".hc-wordmark")?.getBoundingClientRect().width||111;const ns=getComputedStyle(n);const children=Array.from(n.children) as HTMLElement[];const navWidth=children.reduce((w,a)=>w+a.getBoundingClientRect().width,0)+(parseFloat(ns.columnGap)||24)*Math.max(0,children.length-1);const actions=el.querySelector<HTMLElement>(".hc-header-actions");const entryWidth=actions?.querySelector<HTMLElement>(".hc-header-entry-links")?.scrollWidth||0;const authWidth=actions?.querySelector<HTMLElement>(".hc-header-auth")?.scrollWidth||0;const groups=(entryWidth?1:0)+(authWidth?1:0)+(search?1:0);const actionWidth=entryWidth+authWidth+Math.max(0,groups-1)*24;const fullSearch=search?(parseFloat(getComputedStyle(h).getPropertyValue("--hc-search-expanded-width"))||160):0;const next=resolvePortalHeaderLayout({viewport,available,logo,nav:navWidth,actions:actionWidth,fullSearch,iconSearch:search?32:0,gap});setLayout(old=>old.mobile===next.mobile&&old.compactSearch===next.compactSearch&&old.wrapped===next.wrapped?old:next);if(h.parentElement)h.parentElement.style.setProperty("--hc-header-height",`${h.getBoundingClientRect().height}px`)}function schedule(){cancelAnimationFrame(frame);frame=requestAnimationFrame(update)}schedule();const observer=typeof ResizeObserver!=="undefined"?new ResizeObserver(schedule):null;observer?.observe(el);window.addEventListener("resize",schedule);document.fonts?.ready.then(schedule);return()=>{cancelAnimationFrame(frame);observer?.disconnect();window.removeEventListener("resize",schedule)}},[links,actionEntries,search])
 React.useEffect(()=>{if(!open)return;const h=header.current;if(!h)return;const oldOverflow=document.body.style.overflow;document.body.style.overflow="hidden";const siblings=Array.from(h.parentElement?.children||[]).filter(n=>n!==h) as HTMLElement[];const oldInert=siblings.map(n=>n.inert);siblings.forEach(n=>n.inert=true);const frame=requestAnimationFrame(()=>h.querySelector<HTMLButtonElement>(".hc-mobile-menu-category")?.focus());const resize=()=>{if(window.innerWidth>768)setOpen(false)};const trap=(e:KeyboardEvent)=>{if(e.key!=="Tab")return;const list=Array.from(h.querySelectorAll<HTMLElement>("a[href],button,input,summary")).filter(n=>n.getClientRects().length&&!n.hasAttribute("disabled"));const first=list[0],last=list[list.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}};window.addEventListener("resize",resize);h.addEventListener("keydown",trap);return()=>{cancelAnimationFrame(frame);document.body.style.overflow=oldOverflow;siblings.forEach((n,i)=>n.inert=oldInert[i]);h.removeEventListener("keydown",trap);window.removeEventListener("resize",resize);menu.current?.focus()}},[open])
 React.useEffect(()=>{if(!open&&!searchOpen)return;const close=(e:KeyboardEvent)=>{if(e.key==="Escape"){setOpen(false);setSearchOpen(false);menu.current?.focus()}};window.addEventListener("keydown",close);return()=>window.removeEventListener("keydown",close)},[open,searchOpen])
 return <header ref={header} className={`hc-header hc-header-${scene} ${variant==="site"?"hc-header-site":""} hc-header-responsive ${layout.compactSearch?"is-search-compact":""} ${layout.wrapped?"is-wrapped":""}`} data-component="portal-header">
 {variant==="site"&&<div className="hc-site-strip"><div className="por-container"><span>{portalText("portal.text.811d48f28035")}</span><a href="https://www.huaweicloud.com/mobile_app/hwapp.html?channel=navigation_right">{portalText("portal.text.8c68f293506d")}</a></div></div>}<div ref={inner} className="hc-header-inner por-container"><a className="hc-wordmark" href="https://www.huaweicloud.com/" aria-label={portalText("portal.label.7895516d3e96")}><PortalAsset assetId="navigation-logo" alt={portalText("portal.label.4f5d0b82a300")} className="hc-brand-logo"/></a>
 <nav ref={nav} id={id} aria-label={scene==="developer"?portalText("portal.label.c9fee2555ab9"):portalText("portal.label.e792a0f28d4c")} className="hc-navigation">{scene==="developer"&&<a className="hc-column-title" href="https://developer.huaweicloud.com/">{portalText("portal.text.38084d301e3f")}</a>}{links.map(l=><a key={l.label} href={l.href} onClick={()=>setOpen(false)}>{l.label}</a>)}</nav>
 <PortalHeaderActions full={variant==="site"||scene==="developer"} entries={actionEntries} searchEnabled={search} compactSearch={layout.compactSearch}/>
 <div className="hc-header-mobile-controls">{search&&<button type="button" aria-label={searchOpen?portalText("portal.label.ab008ef18dac"):portalText("portal.label.5e9e915d6fba")} aria-expanded={searchOpen} aria-controls={searchId} onClick={()=>{setSearchOpen(!searchOpen);setOpen(false)}}><PortalNavigationGlyph kind="search"/></button>}<a href="https://auth.huaweicloud.com/authui/login?locale=zh-cn" aria-label={portalText("portal.label.d9a999a7c8e8")}><PortalNavigationGlyph kind="user"/></a><button ref={menu} type="button" aria-label={open?portalText("portal.label.baf9f5c82ab8"):portalText("portal.label.38e4f2ee1b9a")} aria-expanded={open} aria-controls={`${id}-mobile`} onClick={()=>{setOpen(!open);setSearchOpen(false)}}><span className={`hc-mobile-menu-glyph ${open?"is-open":""}`} aria-hidden="true"><span/><span/><span/></span></button></div></div>
 {open&&<PortalMobileMenu id={`${id}-mobile`} groups={mobileMenu||(scene==="developer"?developerMobileMenu:[{label:portalText("portal.label.e792a0f28d4c"),items:links},{label:portalText("portal.label.5d52d4478187"),items:actionEntries||[{label:portalText("portal.label.2687ccdbb1d2"),href:"https://support.huaweicloud.com/"},{label:portalText("portal.label.d0d07d153161"),href:"https://console.huaweicloud.com/"}]}])} onNavigate={()=>setOpen(false)} onClose={()=>setOpen(false)}/>}
 {searchOpen&&<div id={searchId} className="hc-header-mobile-search"><PortalHeaderActions entries={[]} searchEnabled/></div>}</header>
}
export function PortalMobileMenu({id,groups,onNavigate,onClose}:{id:string;groups:PortalMobileMenuGroup[];onNavigate:()=>void;onClose:()=>void}){
 const [active,setActive]=React.useState(0);const current=groups[active]||groups[0]
 return <div id={id} className="hc-mobile-menu" role="dialog" aria-modal="true" aria-label={portalText("portal.label.202262896de2")}><div className="hc-mobile-menu-categories" aria-label={portalText("portal.label.d9404303e9f5")}>{groups.map((g,i)=><button key={g.label} className={`hc-mobile-menu-category ${i===active?"is-active":""}`} aria-pressed={i===active} onClick={()=>setActive(i)}>{g.label}</button>)}</div><nav key={active} className="hc-mobile-menu-content" aria-label={current?.label}>{current?.items.map((item,i)=><PortalMobileMenuBranch key={`${item.label}-${i}`} item={item} onNavigate={onNavigate} accordionName={`${id}-${active}`}/>)}</nav><button className="hc-mobile-menu-collapse" type="button" aria-label={portalText("portal.label.95ddfcc9901d")} onClick={onClose}><svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="m4 10 4-4 4 4" stroke="currentColor" strokeWidth="1.5"/></svg></button></div>
}
export function PortalMobileMenuBranch({item,onNavigate,accordionName}:{item:PortalMobileMenuItem;onNavigate:()=>void;accordionName?:string}){
 if(item.children?.length)return <details name={accordionName} className="hc-mobile-menu-branch"><summary>{item.label}<svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="m4 6 4 4 4-4" stroke="currentColor" strokeWidth="1.5"/></svg></summary><div>{item.href&&<a href={item.href} onClick={onNavigate}>{item.label}<span aria-hidden="true">{portalText("portal.text.1273c66ca1ec")}</span></a>}{item.children.map((child,i)=><PortalMobileMenuBranch key={`${child.label}-${i}`} item={child} onNavigate={onNavigate} accordionName={`${accordionName}-${item.label}`}/>)}</div></details>
 return item.href?<a href={item.href} className="hc-mobile-menu-link" onClick={onNavigate}>{item.label}</a>:<span>{item.label}</span>
}
export function PortalNavigationGlyph({kind}:{kind:"search"|"user"|"menu"|"close"}){return <svg width={24} height={24} viewBox="0 0 24 24" fill="none" aria-hidden="true" data-navigation-glyph={kind}>{kind==="search"?<><circle cx="10" cy="10" r="6" stroke="currentColor" strokeWidth="1.5"/><path d="M14.5 14.5L20 20" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></>:kind==="user"?<><g fillRule="evenodd" stroke="var(--hc-t-navigation-user-stroke)" strokeWidth="2"><circle cx="12" cy="12" r="10"/><path d="M12 14a4.002 4.002 0 0 0 0-8 4 4 0 1 0 0 8Z"/><path d="M18.604 19.75a6.668 6.668 0 0 0-13.176-.208"/></g></>:<path d={kind==="menu"?"M4 6H20M4 12H20M4 18H20":"M5 5L19 19M19 5L5 19"} stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/>}</svg>}

