async function copyPortalText(command:string){let timer:ReturnType<typeof setTimeout>|undefined;try{if(!navigator.clipboard)throw Error("manual");await Promise.race([navigator.clipboard.writeText(command),new Promise<never>((_resolve,reject)=>{timer=setTimeout(()=>reject(Error("copy timeout")),10000)})])}finally{if(timer)clearTimeout(timer)}}
export function PortalCopyCommand({command}:{command:string}) {
  const [status,setStatus]=React.useState("")
  const text=React.useRef<HTMLTextAreaElement>(null);const pending=React.useRef(false);const [busy,setBusy]=React.useState(false)
  async function copy(){if(pending.current)return;pending.current=true;setBusy(true);try{await copyPortalText(command);setStatus(portalText("portal.label.8f6f8d979c98"))}catch{text.current?.focus();text.current?.select();setStatus(portalText("portal.label.b3459b3582c1"))}finally{pending.current=false;setBusy(false)}}
  return <div className="hc-command" data-component="portal-copy-command"><label htmlFor="skill-command">{portalText("portal.text.0e4ba162cc1a")}</label><textarea ref={text} id="skill-command" readOnly value={command}/><PortalButton onClick={copy} variant="dark" disabled={busy}>{portalText("portal.text.605c82dd96bc")}</PortalButton><span role="status" aria-live="polite">{status}</span></div>
}
