export function PortalGaussPartners({items}:{items:GaussContentData["partners"]}){
 const [active,setActive]=React.useState(0);const id=React.useId();const tabs=React.useRef<(HTMLButtonElement|null)[]>([])
 function move(e:React.KeyboardEvent,k:number){let next=k;if(e.key==="ArrowRight")next=(k+1)%items.length;else if(e.key==="ArrowLeft")next=(k+items.length-1)%items.length;else if(e.key==="Home")next=0;else if(e.key==="End")next=items.length-1;else return;e.preventDefault();setActive(next);tabs.current[next]?.focus()}
 return <GaussFloor id="gauss-partners" title={portalText("portal.label.944e8d3dd3e7")} grey><div role="tablist" aria-label={portalText("portal.label.610b4ad23a31")} className="hc-gauss-tabs">{items.map((i,k)=><button key={i.title} ref={e=>{tabs.current[k]=e}} id={`${id}-tab-${k}`} role="tab" type="button" aria-selected={active===k} aria-controls={`${id}-panel-${k}`} tabIndex={active===k?0:-1} onClick={()=>setActive(k)} onKeyDown={e=>move(e,k)}>{i.title}</button>)}</div>{items.map((i,k)=><div key={i.title} role="tabpanel" id={`${id}-panel-${k}`} aria-labelledby={`${id}-tab-${k}`} hidden={active!==k} className="hc-gauss-partner-panel"><PortalAsset assetId={i.asset} alt={`${i.title}${portalText("portal.template.cb8781572265")}`} className="hc-gauss-partner-desktop"/><PortalAsset assetId={i.tabletAsset} alt={`${i.title}${portalText("portal.template.cb8781572265")}`} className="hc-gauss-partner-tablet"/><PortalAsset assetId={i.mobileAsset} alt={`${i.title}${portalText("portal.template.cb8781572265")}`} className="hc-gauss-partner-mobile"/></div>)}</GaussFloor>
}
