type FoldedMediaItem={title:string;paragraphs:string[];asset:string;mobileAsset?:string;tag?:string}
export function PortalFoldedMedia({id,title,items,backgroundAsset,defaultIndex=0}:{id:string;title:string;items:FoldedMediaItem[];backgroundAsset?:string;defaultIndex?:number}){
 const [active,setActive]=React.useState(Math.max(0,Math.min(defaultIndex,items.length-1)));const uid=React.useId();const triggers=React.useRef<(HTMLButtonElement|null)[]>([])
 function move(e:React.KeyboardEvent,k:number){let next=k;if(e.key==="ArrowDown")next=(k+1)%items.length;else if(e.key==="ArrowUp")next=(k+items.length-1)%items.length;else if(e.key==="Home")next=0;else if(e.key==="End")next=items.length-1;else return;e.preventDefault();triggers.current[next]?.focus()}
 return <div className="hc-gauss-floor hc-folded-floor">{backgroundAsset&&<PortalAsset assetId={backgroundAsset} alt="" className="hc-folded-background"/>}<PortalSection id={id} title={title}><div className="hc-folded-media"><div className="hc-folded-list">{items.map((item,k)=><article className={`hc-folded-item ${active===k?"is-expanded":""}`} key={item.title}><h3><button type="button" ref={el=>{triggers.current[k]=el}} id={`${uid}-trigger-${k}`} aria-expanded={active===k} aria-controls={`${uid}-panel-${k}`} onClick={()=>setActive(active===k?-1:k)} onKeyDown={e=>move(e,k)}><span>{item.title}{item.tag&&<span className="hc-folded-tag">{item.tag}</span>}</span><span className="hc-faq-chevron" aria-hidden="true"/></button></h3><div className="hc-folded-panel" id={`${uid}-panel-${k}`} role="region" aria-labelledby={`${uid}-trigger-${k}`} hidden={active!==k}>{item.paragraphs.map((paragraph,j)=><p key={j}>{paragraph}</p>)}<PortalAsset assetId={item.mobileAsset||item.asset} alt={item.title} className="hc-folded-inline-media"/></div></article>)}</div><div className="hc-folded-art">{items.map((item,k)=><div key={item.title} hidden={active!==k} className="hc-folded-art-panel"><PortalAsset assetId={item.asset} alt={item.title} className="hc-folded-art-desktop"/><PortalAsset assetId={item.mobileAsset||item.asset} alt={item.title} className="hc-folded-art-mobile"/></div>)}</div></div></PortalSection></div>
}
type SolutionMediaItem={title:string;description:string;href?:string;asset?:string;theme?:string}
export function PortalSolutionCards({id,title,items}:{id:string;title:string;items:SolutionMediaItem[]}){
 const track=React.useRef<HTMLDivElement>(null);const [position,setPosition]=React.useState({start:true,end:false})
 function update(){const el=track.current;if(el){const start=el.scrollLeft<=1,end=el.scrollLeft+el.clientWidth>=el.scrollWidth-1,focused=document.activeElement,controls=el.parentElement;if(start&&focused===controls?.querySelector(".hc-solutions-prev")||end&&focused===controls?.querySelector(".hc-solutions-next"))el.focus({preventScroll:true});setPosition({start,end})}}
 React.useEffect(()=>{update();window.addEventListener("resize",update);return()=>window.removeEventListener("resize",update)},[items.length])
 function scroll(direction:number){const el=track.current;if(el){const card=el.firstElementChild as HTMLElement|null;el.scrollBy({left:direction*((card?.offsetWidth||320)+parseFloat(getComputedStyle(el).gap||"0")),behavior:window.matchMedia("(prefers-reduced-motion: reduce)").matches?"auto":"smooth"})}}
 return <div className="hc-gauss-floor hc-solutions-floor"><PortalSection id={id} title={title}><div className="hc-solutions-carousel"><div className="hc-solutions-track" ref={track} tabIndex={0} role="region" aria-label={portalText("portal.label.9cf371c03a04")} onScroll={update}>{items.map(item=><a key={item.title} className={`hc-solution-card ${item.theme==="dark"?"is-dark":"is-light"}`} href={item.href} aria-label={item.title}>{item.asset&&<PortalAsset assetId={item.asset} alt="" className="hc-solution-background"/>}<div className="hc-solution-copy"><h3>{item.title}</h3><p>{item.description}</p></div><span className="hc-solution-action" aria-hidden="true"><PortalAsset assetId={item.theme==="dark"?"solution-arrow-white":"solution-arrow-dark"} alt="" className="hc-solution-arrow"/></span></a>)}</div><button type="button" className="hc-solutions-prev" aria-label={portalText("portal.label.4e4928145dad")} disabled={position.start} onClick={()=>scroll(-1)}><PortalAsset assetId="solution-carousel-arrow" alt="" className="hc-solutions-carousel-icon"/></button><button type="button" className="hc-solutions-next" aria-label={portalText("portal.label.ba0079cf0e93")} disabled={position.end} onClick={()=>scroll(1)}><PortalAsset assetId="solution-carousel-arrow" alt="" className="hc-solutions-carousel-icon"/></button></div></PortalSection></div>
}

