export function PortalHeaderActions({full=false,entries,searchEnabled=false,onSearch,compactSearch=false}:{full?:boolean;entries?:Link[];searchEnabled?:boolean;compactSearch?:boolean;onSearch?:(query:string)=>void}){
 const [query,setQuery]=React.useState("");const [status,setStatus]=React.useState("");const [expanded,setExpanded]=React.useState(false);const input=React.useRef<HTMLInputElement>(null)
 const links=entries||(full?[{label:portalText("portal.label.2687ccdbb1d2"),href:"https://support.huaweicloud.com/"},{label:portalText("portal.label.71942f7519d5"),href:"https://beian.huaweicloud.com/"},{label:portalText("portal.label.d0d07d153161"),href:"https://console.huaweicloud.com/?locale=zh-cn"}]:[{label:portalText("portal.label.2687ccdbb1d2"),href:"https://support.huaweicloud.com/"}])
 function search(e:React.FormEvent){e.preventDefault();if(compactSearch&&!expanded){setExpanded(true);requestAnimationFrame(()=>input.current?.focus());return}const q=query.trim();if(!q)return;if(onSearch){onSearch(q);return}const match=Array.from(document.querySelectorAll<HTMLElement>("main h1,main h2,main h3")).find(n=>n.textContent?.toLowerCase().includes(q.toLowerCase()));if(match){match.scrollIntoView({block:"center",behavior:"smooth"});setStatus("")}else setStatus(portalText("portal.label.b558b4f9cf19"))}
 return <div className="hc-header-actions">{searchEnabled&&<form className={`hc-header-search ${compactSearch?"is-compact":""} ${expanded?"is-expanded":""}`} role="search" onSubmit={search}><button type="submit" aria-label={portalText("portal.label.44ce7ae909bb")}><svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><circle cx="8.5" cy="8.5" r="5.5" stroke="currentColor" strokeWidth="1.5"/><path d="M12.5 12.5L17 17" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/></svg></button><input ref={input} type="search" value={query} onChange={e=>setQuery(e.target.value)} placeholder={portalText("portal.label.44ce7ae909bb")} aria-label={portalText("portal.label.d0fb0a6465c8")}/><span role="status" className="hc-header-search-status">{status}</span></form>}<div className="hc-header-entry-links">{links.map(l=><a key={l.label} href={l.href}>{l.label}</a>)}</div>{full&&<div className="hc-header-auth"><a href="https://auth.huaweicloud.com/authui/login?locale=zh-cn">{portalText("portal.text.1e2df9c3075a")}</a><a className="hc-header-register" href="https://reg.huaweicloud.com/registerui/public/custom/register.html?locale=zh-cn">{portalText("portal.text.c4fb62202bad")}</a></div>}</div>
}

